using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using System.Threading.Tasks;using NetScope;
public static class CollectorLocalTest {
 static TcpListener listener;static volatile bool running;static int port,headCount,destinationCount,active,maxActive;
 public static void Main(){try{Console.WriteLine(Run());}catch(Exception ex){Console.WriteLine("TEST FAIL "+ex.GetType().Name+": "+ex.Message);Environment.ExitCode=1;}}
 public static string Run(){IWebProxy oldProxy=WebRequest.DefaultWebProxy;WebRequest.DefaultWebProxy=null;listener=new TcpListener(IPAddress.Loopback,0);listener.Start();port=((IPEndPoint)listener.LocalEndpoint).Port;running=true;Task.Factory.StartNew(ServerLoop);
 try{var collector=new NetworkCollector();var targets=new List<ProbeTarget>();int[] codes={200,401,403,404,405,429,503,302,407};foreach(int code in codes)targets.Add(new ProbeTarget{Id=code.ToString(),Name=code.ToString(),Url="http://127.0.0.1:"+port+"/"+code});targets.Add(new ProbeTarget{Id="disabled",Url="http://127.0.0.1:"+port+"/destination",Enabled=false});
 var results=collector.ProbeAsync(targets,3).GetAwaiter().GetResult();if(results.Count!=9)throw new Exception("Disabled filtering failed");foreach(var result in results)if(!result.Reachable||result.StatusCode!=Int32.Parse(result.TargetId))throw new Exception("Status classification failed: "+result.TargetId+" "+result.Error);
 if(results[1].Outcome!="AuthRequired"||results[2].Outcome!="Forbidden"||results[3].Outcome!="NotFound"||results[4].Outcome!="MethodNotAllowed"||results[5].Outcome!="RateLimited"||results[6].Outcome!="ServerError"||results[7].Outcome!="Redirect"||results[8].Outcome!="ProxyAuthRequired"||!results[8].Error.Contains("尚未验证目标服务"))throw new Exception("Outcome distinction failed");if(destinationCount!=0||headCount!=9||maxActive>4)throw new Exception("HEAD/redirect/concurrency check failed");
 var watch=Stopwatch.StartNew();var slow=collector.ProbeAsync(new List<ProbeTarget>{new ProbeTarget{Id="slow",Url="http://127.0.0.1:"+port+"/slow"}},1).GetAwaiter().GetResult()[0];double elapsed=watch.Elapsed.TotalMilliseconds;if(slow.Reachable||slow.Outcome!="Timeout"||elapsed>2000)throw new Exception("Deadline check failed: "+elapsed+" "+slow.Outcome);
 var invalid=collector.ProbeAsync(new List<ProbeTarget>{new ProbeTarget{Url="ftp://localhost/file"}},1).GetAwaiter().GetResult()[0];if(invalid.Outcome!="InvalidUrl")throw new Exception("Invalid URL accepted");WebRequest.DefaultWebProxy=new SlowProxy();var blockedCollector=new NetworkCollector();var blockedTargets=new List<ProbeTarget>();for(int i=0;i<5;i++)blockedTargets.Add(new ProbeTarget{Id="blocked"+i,Url="http://127.0.0.1:"+port+"/200"});var blocked=blockedCollector.ProbeAsync(blockedTargets,1).GetAwaiter().GetResult();foreach(var r in blocked)if(r.Outcome!="Skipped"||r.Reachable)throw new Exception("Internal contention mislabeled: "+r.Outcome);
WebRequest.DefaultWebProxy=null;var local=new NetworkCollector();bool first=local.CaptureLocal("auto").TrafficRateReady;Thread.Sleep(200);bool second=local.CaptureLocal("auto").TrafficRateReady;if(first||!second)throw new Exception("Counter warmup flag incorrect");Thread.Sleep(10100);if(local.CaptureLocal("auto").TrafficRateReady)throw new Exception("Stale counter interval marked ready");var devices=local.GetNeighborsAsync().GetAwaiter().GetResult();int own=0;foreach(var d in devices)if(d.Source=="本机接口 / Windows 自报"&&d.Name==Environment.MachineName)own++;if(own==0)throw new Exception("Missing local self-report");
return "PASS: HTTP status/HEAD/redirect/filter; maxHTTP="+maxActive+"; timeout="+Math.Round(elapsed)+"ms; invalid scheme; internal congestion=Skipped; first and stale rates unready, next sample ready; self-reported local addresses="+own;
 }finally{running=false;listener.Stop();WebRequest.DefaultWebProxy=oldProxy;}}
 static void ServerLoop(){while(running){try{TcpClient client=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(Handle,client);}catch{if(!running)return;}}}
 static void Handle(object value){using(TcpClient client=(TcpClient)value){try{client.ReceiveTimeout=2000;using(NetworkStream stream=client.GetStream()){var reader=new StreamReader(stream,Encoding.ASCII,false,1024,true);string first=reader.ReadLine();if(String.IsNullOrEmpty(first))return;while(!String.IsNullOrEmpty(reader.ReadLine())){}string[] parts=first.Split(' ');if(parts[0]=="HEAD")Interlocked.Increment(ref headCount);string path=parts[1];if(path=="/destination")Interlocked.Increment(ref destinationCount);int current=Interlocked.Increment(ref active);lock(typeof(CollectorLocalTest)){maxActive=Math.Max(maxActive,current);}try{Thread.Sleep(path=="/slow"?2500:100);int code;if(!Int32.TryParse(path.Trim('/'),out code))code=200;string response="HTTP/1.1 "+code+" Test\r\nContent-Length: 0\r\nConnection: close\r\n"+(code==302?"Location: http://127.0.0.1:"+port+"/destination\r\n":"")+"\r\n";byte[] bytes=Encoding.ASCII.GetBytes(response);stream.Write(bytes,0,bytes.Length);}finally{Interlocked.Decrement(ref active);}}}catch{}}}
}


public class SlowProxy:IWebProxy{public ICredentials Credentials{get;set;} public bool IsBypassed(Uri uri){return false;} public Uri GetProxy(Uri uri){Thread.Sleep(3000);return uri;}}

